---@class MainSceneHelper
MainSceneHelper = class("MainSceneHelper")

---@param mainSceneBoxInfo MainSceneBoxInfo
function MainSceneHelper:SetHighLightEffect(mainSceneBoxInfo)
    if  GameObjectIsNull(mainSceneBoxInfo.HighlightEffect) then
        CSFxManager:Get():SetCrashHighLight(mainSceneBoxInfo.HighlightEffect.gameObject)
    end
end

function MainSceneHelper:SetIsCanOperationSign(active)
    CSCinemachineCameraManager.Get():SetIsCanOperationSign(active,false)
end



---@param interactivityType InteractivityType  @ number
---@param blendMode DollyTrackBlendMode @ number
---@param isCanBeBreak boolean @ 该行为时候可以被打断
---@param callBack function @ 移动到目标点后的回调
function MainSceneHelper:MoveToTargetNode(interactivityType,blendMode,isCanBeBreak,callBack,speed)
    MainSceneManager:Get():SetCurInteractivityType(interactivityType)
    local mapNode = MainSceneManager:Get():GetNodeByInteractivityType(interactivityType)
    if mapNode then
        speed = speed and speed or 0.5
        if isCanBeBreak == false then
            self:SetIsCanOperationSign(false)
        end
        local moveOver = function()
            if isCanBeBreak == false then
                self:SetIsCanOperationSign(true)
            end
            if callBack then
                callBack()
            end
        end
        local isExecution= CSCinemachineCameraManager.Get():DollyTrackMoveToNode(mapNode,blendMode,moveOver,speed)
        if isExecution==false then
            if isCanBeBreak == false then
                self:SetIsCanOperationSign(true)
            end
        end
    end
end